yakit.AutoInitYakit()

# Input your code!

options = cli.StringSlice("options", cli.setRequired(true),cli.setVerboseName("选项"),cli.setSelectOption("获取邮箱", "getemail"),cli.setSelectOption("查询邮箱", "selectemail"),cli.setDefault("getemail"))
email = cli.String("email", cli.setVerboseName("查询邮箱"))
cli.check()

getemail = func(){
    req = `POST /api/trpc/email.refreshEmailAddress?batch=1 HTTP/1.1
Host: tempmailpro.org
Connection: keep-alive
Content-Length: 2
sec-ch-ua-platform: "Windows"
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/137.0.0.0 Safari/537.36 Edg/137.0.0.0
sec-ch-ua: "Microsoft Edge";v="137", "Chromium";v="137", "Not/A)Brand";v="24"
content-type: application/json
sec-ch-ua-mobile: ?0
Accept: */*
Origin: https://tempmailpro.org
Sec-Fetch-Site: same-origin
Sec-Fetch-Mode: cors
Sec-Fetch-Dest: empty
Referer: https://tempmailpro.org/zh
Accept-Encoding: gzip, deflate, br, zstd
Accept-Language: zh-CN,zh;q=0.9,en;q=0.8,en-GB;q=0.7,en-US;q=0.6
Cookie: NEXT_LOCALE=zh; _ga_93W6KXLJX2=GS2.1.s%v$o1$g0$t%v$j60$l0$h0; _ga=GA1.1.%v.%v

{}`

    randnum = fuzz.Strings("{{randint(100000000,2000000000)}}")[0]
    t = timestamp()
    req = str.f(req, t,t,randnum,t)
    resp,_,err = poc.HTTP(req, poc.https(true))
    if err != nil{
        yakit.Error("[*] 网络请求失败！")
        die(err)
    }
    if poc.GetStatusCodeFromResponse(resp) != 200{
        yakit.Error(`[*] 响应格式错误！`)
        return
    }
    body = json.loads(poc.GetHTTPPacketBody(resp))
    if len(body) > 0{
        result = body[0]
        e = result["result"]["data"]["email"]
        if len(e) == 0{
            yakit.Error(`[*] 获取邮箱失败！`)
        }else{
            yakit.Info("[*] 邮箱地址：%v"%e)
        }

    }else{
        yakit.Error(`[*] 响应格式错误！`)
        return
    }
}

selectemail = func(e){
    data = str.f(`{"0":{"emailAddress":"%v"}}`, e)
    req = `GET /api/trpc/email.getEmails?batch=1&input=%v HTTP/1.1
Host: tempmailpro.org
Accept-Encoding: gzip, deflate, br
Accept: */*
Accept-Language: en-US;q=0.9,en;q=0.8
User-Agent: Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/134.0.0.0 Safari/537.36
Cache-Control: max-age=0`
    req = str.f(req,codec.EncodeUrl(data))
    resp,_,err = poc.HTTP(req, poc.https(true))
    if err != nil{
        yakit.Error("[*] 网络请求失败！")
        die(err)
    }
    if poc.GetStatusCodeFromResponse(resp) != 200{
        yakit.Error(`[*] 响应格式错误！`)
        return
    }
    body = json.loads(poc.GetHTTPPacketBody(resp))
    if len(body) > 0{
        result = body[0]
        if len(result["result"]["data"]) == 0{
            yakit.Markdown(`- 没有查询到邮件信息！`)
            return 
        }

        for _,item := range result["result"]["data"]{
            printData = ""
            from = "- 发送人" + item["from"] + "\n"
            title = "- 邮件标题" + item["subject"] + "\n"
            msg = "- 邮件内容\n" +"```\n" +item["body"]+"\n```" + "\n"
            printData = from + title + msg
            yakit.Markdown(printData)
        }
    }else{
        yakit.Error(`[*] 响应格式错误！`)
        return
    }
}


if options[0] == "selectemail" && len(email) == 0{
    yakit.Error("[*] 查询邮未输入，请输入查询邮箱！")
}

if options[0] == "selectemail"{
    selectemail(str.TrimSpace(email))
}else{
    getemail()
}
